57	/**
58	 * Gestione asset di un singolo record (digital-hub #16).
59	 *
60	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
61	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
62	 * nella tabella di una resource. La route porta owner via coppia polimorfica
63	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
64	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
65	 *
66	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
67	 * di #16a; qui c'è solo lo scheletro navigabile.
68	 */
69	class AssetManager extends Page implements HasActions
70	{
71	    use InteractsWithActions;
72	
73	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
74	
75	    protected static ?string $slug = 'assets';
76	
77	    protected string $view = 'digital-hub::filament.pages.asset-manager';
78	
79	    protected Width|string|null $maxContentWidth = Width::Full;
80	
81	    /**
82	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
83	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
84	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
85	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
86	     * action continuano a funzionare.
87	     */
88	    protected static string $layout = 'filament-panels::components.layout.base';
89	
90	    /** icona di "sposta", usata per file e cartelle */
91	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
92	
93	    /** Morph alias del record proprietario (es. `product`). */
94	    public string $ownerType;
95	
96	    /** Chiave primaria del record proprietario. */
97	    public int|string $ownerKey;
98	
99	    /** Folder attualmente selezionata; null = root ("Home") del record. */
100	    public ?int $activeFolderId = null;
101	
102	    /**
103	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
104	     * per il link "indietro". null se assente o non locale. È public così
105	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
106	     */
107	    public ?string $returnUrl = null;
108	
109	    /**
110	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
111	     * @var array<int, int|string>
112	     */
113	    public array $selectedAssetIds = [];
114	
115	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
116	    public ?string $lastShareUrl = null;
117	
118	    /**
119	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
120	     * @var (Model&OwnsAssets)|null
121	     */
122	    private ?Model $ownerModel = null;
123	
124	    /**
125	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
126	     * @var null|EloquentCollection<int,AssetFolder>
127	     */
128	    private ?EloquentCollection $folderCache = null;
129	
130	    /**
131	     * Cache per-request dei media contenuti nei sottoalberi delle sottocartelle
132	     * visibili, condivisa tra preview delle tile cartella e check del polling.
133	     * @var null|\Illuminate\Support\Collection<int, Media>
134	     */
135	    private ?\Illuminate\Support\Collection $subfolderMediaCache = null;
136	
137	    #[Override]
138	    public static function getRoutePath(Panel $panel): string
139	    {
140	        return '/assets/{ownerType}/{owner}';
141	    }
142	
143	    public static function shouldRegisterNavigation(): bool
144	    {
145	        return false;
146	    }
147	
148	    /**
149	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
150	     */
151	    public function mount(string $ownerType, int|string $owner): void
152	    {
153	        $this->ownerType = $ownerType;
154	        $this->ownerKey = $owner;
155	
156	        // valida subito: record risolvibile e dotato del trait HasAssets
157	        $this->resolveOwner();
158	
159	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
160	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
161	        // Fallback (link diretto/tab nuova, niente referer): la lista della
162	        // resource del record, senza filtri.
163	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
164	            ?? $this->resourceIndexUrl();
165	    }
166	
167	    /**
168	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
169	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
170	     * pagina asset stessa (es. reload). null se non valido.
171	     */
172	    private function resolveReturnUrl(?string $url): ?string
173	    {
174	        if (! is_string($url) || $url === '') {
175	            return null;
176	        }
177	
178	        $host = parse_url($url, PHP_URL_HOST);
179	        if ($host !== null && $host !== request()->getHost()) {
180	            return null;
181	        }
182	
183	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
184	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
185	            return null;
186	        }
187	
188	        return $url;
189	    }
190	
191	    /**
192	     * URL della lista (index) della resource Filament del record, da usare come
193	     * fallback quando manca un Referer valido. null se il record non ha una
194	     * resource registrata nel pannello o l'URL non è risolvibile.
195	     */
196	    private function resourceIndexUrl(): ?string
197	    {
198	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
199	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
200	        if ($resource === null) {
201	            return null;
202	        }
203	
204	        try {
205	            $url = $resource::getUrl('index');
206	
207	            return $url ?: null;
208	        } catch (\Throwable) {
209	            return null;
210	        }
211	    }
212	
213	    /**
214	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
215	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
216	     *
217	     * @return Model&OwnsAssets
218	     */
219	    public function resolveOwner(): Model
220	    {
221	        if ($this->ownerModel !== null) {
222	            return $this->ownerModel;
223	        }
224	
225	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
226	        abort_unless(class_exists($class), 404);
227	
228	        /** @var class-string<Model> $class */
229	        $record = $class::query()->find($this->ownerKey);
230	        abort_unless($record instanceof OwnsAssets, 404);
231	
232	        return $this->ownerModel = $record;
233	    }
234	
235	    #[Override]
236	    public function getTitle(): string|Htmlable
237	    {
238	        $owner = $this->resolveOwner();
239	        $name = $owner->getAttribute('name');
240	        $key = $owner->getKey();
241	        $label = is_string($name) && $name !== ''
242	            ? $name
243	            : '#' . (is_scalar($key) ? (string) $key : '');
244	
245	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
246	    }
247	
248	    /**
249	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
250	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
251	     * disegna affatto l'header, evitando il doppione.
252	     */
253	    #[Override]
254	    public function getHeading(): string|Htmlable
255	    {
256	        return '';
257	    }
258	
259	    /**
260	     * Tutte le folder del record, caricate una sola volta per request.
261	     *
262	     * @return EloquentCollection<int, AssetFolder>
263	     */
264	    public function allFolders(): EloquentCollection
265	    {
266	        if ($this->folderCache !== null) {
267	            return $this->folderCache;
268	        }
269	
270	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
271	    }
272	
273	    /**
274	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
275	     * record (es. manomissione del payload Livewire).
276	     */
277	    public function selectFolder(?int $folderId): void
278	    {
279	        // cambiando vista la selezione corrente non ha più senso
280	        $this->selectedAssetIds = [];
281	
282	        if ($folderId === null) {
283	            $this->activeFolderId = null;
284	
285	            return;
286	        }
287	
288	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
289	            $this->activeFolderId = $folderId;
290	        }
291	    }
292	
293	    /**
294	     * Svuota la selezione corrente (pulsante "Annulla selezione").
295	     */
296	    public function clearAssetSelection(): void
297	    {
298	        $this->selectedAssetIds = [];
299	    }
300	
301	    /**
302	     * Seleziona tutti gli asset attualmente visibili nella vista corrente
303	     * (pulsante "Seleziona tutti", disponibile dopo la prima selezione).
304	     */
305	    public function selectAllAssets(): void
306	    {
307	        $this->selectedAssetIds = $this->getAssets()
308	            ->map(function (Media $media): string {
309	                $key = $media->getKey();
310	
311	                return is_int($key) || is_string($key) ? (string) $key : '';
312	            })
313	            ->all();
314	    }
315	
316	    /**
317	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
318	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
319	     */
320	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
321	    {
322	        $media = $this->findOwnedMedia($mediaId);
323	        if ($media === null) {
324	            return;
325	        }
326	
327	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
328	            $folderId = null;
329	        }
330	
331	        $media->setAttribute('asset_folder_id', $folderId);
332	        $media->save();
333	
334	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
335	    }
336	
337	    /**
338	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
339	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
340	     * posizione. Gli id estranei al record sono ignorati.
341	     *
342	     * @param array<int, int|string> $orderedIds
343	     */
344	    public function reorderFolders(array $orderedIds): void
345	    {
346	        foreach (array_values($orderedIds) as $index => $id) {
347	            $folder = $this->findOwnedFolder($id);
348	            if ($folder === null) {
349	                continue;
350	            }
351	
352	            if ($folder->sort !== $index) {
353	                $folder->sort = $index;
354	                $folder->save();
355	            }
356	        }
357	
358	        $this->folderCache = null;
359	    }
360	
361	    /**
362	     * Albero annidato delle folder del record per il pannello sinistro.
363	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
364	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
365	     *
366	     * @return array<int, array{folder: AssetFolder, children: mixed}>
367	     */
368	    public function getFolderTree(): array
369	    {
370	        return $this->buildTree(null);
371	    }
372	
373	    /**
374	     * @return array<int, array{folder: AssetFolder, children: mixed}>
375	     */
376	    private function buildTree(?int $parentId): array
377	    {
378	        return $this->allFolders()
379	            ->where('parent_id', $parentId)
380	            ->map(fn (AssetFolder $folder): array => [
381	                'folder' => $folder,
382	                'children' => $this->buildTree($folder->id),
383	            ])
384	            ->values()
385	            ->all();
386	    }
387	
388	    /**
389	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
390	     * pannello destro insieme ai file. In root ("Home") sono le cartelle di
391	     * primo livello: la root si naviga come una cartella qualunque.
392	     *
393	     * @return \Illuminate\Support\Collection<int, AssetFolder>
394	     */
395	    public function getSubfolders(): \Illuminate\Support\Collection
396	    {
397	        return $this->allFolders()
398	            ->where('parent_id', $this->activeFolderId)
399	            ->values();
400	    }
401	
402	    /**
403	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
404	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
405	     *
406	     * @return list<AssetFolder>
407	     */
408	    public function getBreadcrumbTrail(): array
409	    {
410	        if ($this->activeFolderId === null) {
411	            return [];
412	        }
413	
414	        $folders = $this->allFolders();
415	        $trail = [];
416	        $id = $this->activeFolderId;
417	
418	        while ($id !== null) {
419	            $folder = $folders->firstWhere('id', $id);
420	            if (! $folder instanceof AssetFolder) {
421	                // folder eliminata sotto i piedi: torna a root
422	                $this->activeFolderId = null;
423	
424	                return [];
425	            }
426	
427	            array_unshift($trail, $folder);
428	            $id = $folder->parent_id;
429	        }
430	
431	        return $trail;
432	    }
433	
434	    /**
435	     * Media mostrati nel pannello destro: i soli media diretti della folder
436	     * attiva. In root ("Home") sono i file caricati direttamente in root
437	     * (nessuna folder assegnata), come in una cartella qualunque.
438	     *
439	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
440	     */
441	    public function getAssets(): \Illuminate\Support\Collection
442	    {
443	        $folder = $this->activeFolderId !== null
444	            ? $this->findOwnedFolder($this->activeFolderId)
445	            : null;
446	
447	        return $this->resolveOwner()->assetsInFolder($folder);
448	    }
449	
450	    // -- Preview delle cartelle (14b) -----------------------------------------
451	
452	    /** Numero massimo di miniature nel collage della tile cartella. */
453	    public const FOLDER_PREVIEW_LIMIT = 4;
454	
455	    /**
456	     * Miniature per le tile delle sottocartelle: per ogni sottocartella diretta
457	     * della folder attiva, fino a FOLDER_PREVIEW_LIMIT URL di anteprima presi
458	     * dai media contenuti nella cartella o nei suoi discendenti (ordine
459	     * order_column, come la griglia). "Mostrabile" = ha il poster generato dal
460	     * job, oppure è un'immagine (l'originale è già leggero). I media ancora in
461	     * lavorazione o senza anteprima vengono saltati: la tile ricade sull'icona
462	     * finché non c'è nulla di mostrabile.
463	     *
464	     * Derivata pura, niente da persistere: se il contenuto della cartella cambia
465	     * (spostamenti, delete, job completati) il prossimo render riflette lo stato.
466	     *
467	     * @return array<int, list<string>> id sottocartella => URL miniature
468	     */
469	    public function getSubfolderPreviews(): array
470	    {
471	        $tileMap = $this->tileBySubtreeFolder();
472	
473	        $previews = [];
474	        foreach ($this->getSubfolders() as $subfolder) {
475	            $previews[$subfolder->id] = [];
476	        }
477	
478	        foreach ($this->subfolderMedia() as $media) {
479	            $tileId = $this->tileForMedia($media, $tileMap);
480	            if ($tileId === null || count($previews[$tileId]) >= self::FOLDER_PREVIEW_LIMIT) {
481	                continue;
482	            }
483	
484	            // stessa catena di fallback della card asset: poster → originale se immagine
485	            $url = AssetPreview::url($media)
486	                ?? (AssetFileType::fromMedia($media)->isImage() ? AssetUrl::original($media) : null);
487	
488	            if ($url !== null) {
489	                $previews[$tileId][] = $url;
490	            }
491	        }
492	
493	        return $previews;
494	    }
495	
496	    /**
497	     * Numero totale di file per ogni sottocartella visibile, discendenti
498	     * compresi, mostrato sotto il nome della tile. Conta sulla collezione già
499	     * caricata per le preview ({@see self::subfolderMedia()}): nessuna query
500	     * aggiuntiva.
501	     *
502	     * @return array<int, int> id sottocartella => numero di file nel sottoalbero
503	     */
504	    public function getSubfolderFileCounts(): array
505	    {
506	        $tileMap = $this->tileBySubtreeFolder();
507	
508	        $counts = [];
509	        foreach ($this->getSubfolders() as $subfolder) {
510	            $counts[$subfolder->id] = 0;
511	        }
512	
513	        foreach ($this->subfolderMedia() as $media) {
514	            $tileId = $this->tileForMedia($media, $tileMap);
515	            if ($tileId !== null) {
516	                $counts[$tileId]++;
517	            }
518	        }
519	
520	        return $counts;
521	    }
522	
523	    /**
524	     * Mappa ogni folder dei sottoalberi visibili (sottocartella diretta della
525	     * folder attiva o sua discendente) all'id della sottocartella-tile che la
526	     * contiene. Camminata sull'albero già in memoria.
527	     *
528	     * @return array<int, int>
529	     */
530	    private function tileBySubtreeFolder(): array
531	    {
532	        $map = [];
533	
534	        foreach ($this->getSubfolders() as $subfolder) {
535	            foreach ($this->descendantFolderIds($subfolder) as $id) {
536	                $map[$id] = $subfolder->id;
537	            }
538	        }
539	
540	        return $map;
541	    }
542	
543	    /**
544	     * Id della sottocartella-tile a cui il media afferisce (direttamente o via
545	     * discendenti), o null se fuori dai sottoalberi visibili.
546	     *
547	     * @param array<int, int> $tileMap da {@see self::tileBySubtreeFolder()}
548	     */
549	    private function tileForMedia(Media $media, array $tileMap): ?int
550	    {
551	        $folderId = $media->getAttribute('asset_folder_id');
552	
553	        return is_numeric($folderId) ? ($tileMap[(int) $folderId] ?? null) : null;
554	    }
555	
556	    /**
557	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
558	     * almeno uno in lavorazione: estende il polling della griglia (che guarda
559	     * solo gli asset della folder attiva) così le preview delle tile cartella
560	     * compaiono da sole a job concluso.
561	     */
562	    public function hasProcessingInSubfolders(): bool
563	    {
564	        return $this->subfolderMedia()->contains(
565	            fn (Media $media): bool => $this->assetStatus($media)?->isInProgress() ?? false,
566	        );
567	    }
568	
569	    /**
570	     * Id della folder e di tutte le sue discendenti, camminando l'albero già
571	     * cachato in memoria ({@see self::allFolders()}): nessuna query aggiuntiva.
572	     *
573	     * @return list<int>
574	     */
575	    private function descendantFolderIds(AssetFolder $folder): array
576	    {
577	        $ids = [$folder->id];
578	
579	        foreach ($this->allFolders()->where('parent_id', $folder->id) as $child) {
580	            $ids = array_merge($ids, $this->descendantFolderIds($child));
581	        }
582	
583	        return $ids;
584	    }
585	
586	    /**
587	     * Media contenuti nei sottoalberi delle sottocartelle della folder attiva,
588	     * in una sola query (niente N+1 sulle tile), cachati per la request.
589	     *
590	     * @return \Illuminate\Support\Collection<int, Media>
591	     */
592	    private function subfolderMedia(): \Illuminate\Support\Collection
593	    {
594	        if ($this->subfolderMediaCache !== null) {
595	            return $this->subfolderMediaCache;
596	        }
597	
598	        $ids = [];
599	        foreach ($this->getSubfolders() as $subfolder) {
600	            $ids = array_merge($ids, $this->descendantFolderIds($subfolder));
601	        }
602	
603	        if ($ids === []) {
604	            return $this->subfolderMediaCache = new \Illuminate\Support\Collection();
605	        }
606	
607	        $owner = $this->resolveOwner();
608	
609	        return $this->subfolderMediaCache = $owner->media()
610	            ->where('collection_name', $owner->assetsCollection())
611	            ->whereIn('asset_folder_id', $ids)
612	            ->orderBy('order_column')
613	            ->get()
