806	    /**
807	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
808	     * I file finiscono nella collection asset del record (disco scoped).
809	     */
810	    public function uploadAssetsAction(): Action
811	    {
812	        return Action::make('uploadAssets')
813	            ->label(__('digital-hub::assets.upload'))
814	            ->icon(Heroicon::OutlinedArrowUpTray)
815	            ->modalHeading(__('digital-hub::assets.upload_heading'))
816	            ->schema([
817	                FileUpload::make('files')
818	                    ->label(__('digital-hub::assets.files_field'))
819	                    ->multiple()
820	                    ->required()
821	                    ->storeFiles(false),
822	            ])
823	            ->action(function (array $data): void {
824	                $owner = $this->resolveOwner();
825	                $files = $data['files'] ?? [];
826	                if (! is_array($files)) {
827	                    return;
828	                }
829	
830	                $count = 0;
831	                foreach ($files as $file) {
832	                    if (! $file instanceof TemporaryUploadedFile) {
833	                        continue;
834	                    }
835	
836	                    $media = $owner->addMedia($file)
837	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
838	                        ->toMediaCollection($owner->assetsCollection());
839	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
840	
841	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
842	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
843	                    /** @disregard P1013 */
844	                    $user = auth()->user();
845	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
846	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
847	
848	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
849	                    // job in coda: il media entra "pending" finché il job non lo chiude
850	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
851	                    $media->save();
852	
853	                    $this->dispatchProcessing($media);
854	                    $count++;
855	                }
856	
857	                if ($count > 0) {
858	                    Notification::make()
859	                        ->success()
860	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
861	                        ->send();
862	                }
863	            });
864	    }
