1029	     * un blocco per chiave presente (`common`/`exif`/`iptc`/`xmp`). I valori
1030	     * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
1031	     * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
1032	     * metadati (media non ancora processato).
1033	     *
1034	     * @return list<Section>
1035	     */
1036	    private function assetMetadataSections(Media $media): array
1037	    {
1038	        $metadata = ExtractedMetadata::forMedia($media);
1039	
1040	        $labels = [
1041	            'common' => __('digital-hub::assets.meta_block_common'),
1042	            'exif' => 'EXIF',
1043	            'iptc' => 'IPTC',
1044	            'xmp' => 'XMP',
1045	        ];
1046	
1047	        $sections = [];
1048	        foreach ($labels as $key => $label) {
1049	            $block = $metadata[$key] ?? null;
1050	            if (! is_array($block)) {
1051	                continue;
1052	            }
1053	
1054	            $flat = ExtractedMetadata::flatten($block);
1055	            if ($flat === []) {
1056	                continue;
1057	            }
1058	
1059	            $sections[] = Section::make($label)
1060	                ->heading('')
1061	                // ->collapsible()
1062	                // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
1063	                ->schema([
1064	                    Fieldset::make($label)
1065	                        ->columnSpanFull()
1066	                        ->columns(1)
1067	                        ->contained(false)
1068	                        ->schema([
1069	                            KeyValueEntry::make("meta_{$key}")
1070	                                ->hiddenLabel()
1071	                                ->state($flat)
1072	                                ->keyLabel(__('digital-hub::assets.meta_key'))
1073	                                ->valueLabel(__('digital-hub::assets.meta_value')),
1074	                        ]),
1075	                ]);
1076	        }
1077	
1078	        return $sections;
1079	    }
