17	/**
18	 * Token di accesso a un set di asset (digital-hub 22e/22g).
19	 *
20	 * Un solo meccanismo per due lifecycle, distinti dalla scadenza:
21	 *  - **download multiplo (22e)**: share effimero (`expires_at` a pochi minuti),
22	 *    creato in silenzio dall'action e prunato in automatico;
23	 *  - **condivisione esterna (22g)**: share persistente (scadenza lunga/assente),
24	 *    con password opzionale e gallery pubblica `/share/{token}` (la UI di
25	 *    gestione/revoca è il follow-up 22h).
26	 *
27	 * Il token (random, opaco) è il segreto d'accesso: il controller di download
28	 * risolve lo share dal token e verifica che non sia scaduto. Il set di media è
29	 * una relazione N-N con FK reali (cascade), quindi un media eliminato esce dallo
30	 * share da solo.
31	 *
32	 * @property int $id
33	 * @property string $token
34	 * @property string|null $name
35	 * @property string|null $password
36	 * @property Carbon|null $expires_at
37	 * @property Carbon|null $last_accessed_at
38	 * @property int|string|null $created_by
39	 * @property-read \Illuminate\Database\Eloquent\Collection<int, Media> $media
40	 */
41	class AssetShare extends Model
42	{
43	    use Prunable;
44	
45	    protected $guarded = [];
46	
47	    protected $casts = [
48	        'expires_at' => 'datetime',
49	        'last_accessed_at' => 'datetime',
50	    ];
51	
52	    protected static function booted(): void
53	    {
54	        static::creating(function (AssetShare $share): void {
55	            $token = $share->getAttribute('token');
56	            if (! is_string($token) || $token === '') {
57	                $share->token = self::generateToken();
58	            }
59	        });
60	    }
61	
62	    /** Token opaco di accesso (URL-safe). */
63	    public static function generateToken(): string
64	    {
65	        return Str::random(48);
66	    }
67	
68	    /**
69	     * Crea uno share per un set di media, con scadenza opzionale.
70	     *
71	     * @param iterable<int, Media> $media
72	     */
73	    public static function createForMedia(iterable $media, ?DateTimeInterface $expiresAt = null, int|string|null $createdBy = null): self
74	    {
75	        $share = new self();
76	        $share->setAttribute('expires_at', $expiresAt);
77	        $share->setAttribute('created_by', $createdBy);
78	        $share->save();
79	
80	        $ids = collect($media)->map(fn (Media $item) => $item->getKey())->all();
81	        $share->media()->sync($ids);
82	
83	        return $share;
84	    }
85	
86	    /**
87	     * Crea uno share persistente per la condivisione esterna (22g): scadenza
88	     * lunga/assente, nome e password opzionali. La password è salvata hashata.
89	     *
90	     * @param iterable<int, Media> $media
91	     */
92	    public static function createPersistent(iterable $media, ?string $name = null, ?string $plainPassword = null, ?DateTimeInterface $expiresAt = null, int|string|null $createdBy = null): self
93	    {
94	        $share = self::createForMedia($media, $expiresAt, $createdBy);
95	
96	        $share->name = $name !== '' ? $name : null;
97	        $share->setPassword($plainPassword);
98	        $share->save();
99	
100	        return $share;
101	    }
102	
103	    /**
104	     * Media inclusi nello share.
105	     *
106	     * @return BelongsToMany<Media, $this>
107	     */
108	    public function media(): BelongsToMany
109	    {
110	        return $this->belongsToMany(Media::class, 'asset_share_media');
111	    }
112	
113	    /** Vero se lo share ha una scadenza ed è passata. */
114	    public function isExpired(): bool
115	    {
116	        return $this->expires_at !== null && $this->expires_at->isPast();
117	    }
118	
119	    /** Vero se lo share è protetto da password (gate prima della gallery). */
120	    public function hasPassword(): bool
121	    {
122	        return is_string($this->password) && $this->password !== '';
123	    }
124	
125	    /** Imposta (hashata) o azzera la password. Stringa vuota = nessuna password. */
126	    public function setPassword(?string $plain): void
127	    {
128	        $this->password = ($plain === null || $plain === '') ? null : Hash::make($plain);
129	    }
130	
131	    /** Verifica la password in chiaro contro l'hash salvato. */
132	    public function checkPassword(string $plain): bool
133	    {
134	        return $this->hasPassword() && Hash::check($plain, (string) $this->password);
135	    }
136	
137	    /** Registra l'ultimo accesso alla gallery (UI di gestione). */
138	    public function touchAccessed(): void
139	    {
140	        $this->forceFill(['last_accessed_at' => now()])->save();
141	    }
142	
143	    /**
144	     * Chiave di sessione dello sblocco password. Condivisa tra la gallery (gate)
145	     * e la route di download dello zip, così il download non bypassa la password.
146	     */
147	    public function sessionUnlockKey(): string
148	    {
149	        return 'share_' . $this->id . '_unlocked';
150	    }
151	
152	    /**
153	     * Scope: solo share non scaduti (senza scadenza o scadenza futura).
154	     *
155	     * @param Builder<AssetShare> $query
156	     */
157	    public function scopeValid(Builder $query): void
158	    {
159	        $query->where(function (Builder $query): void {
160	            $query->whereNull('expires_at')->orWhere('expires_at', '>', now());
161	        });
162	    }
163	
164	    /**
165	     * Righe da prunare: gli share scaduti (gli effimeri del download). La pivot
166	     * si pulisce in cascata via FK. Schedulato dal service provider.
167	     *
168	     * @return Builder<static>
169	     */
170	    public function prunable(): Builder
171	    {
172	        return static::query()->whereNotNull('expires_at')->where('expires_at', '<', now());
173	    }
174	}
