12	/**
13	 * Costruisce uno zip degli asset in streaming, senza file temporaneo
14	 * (digital-hub 22e). I byte dello zip sono prodotti on-the-fly leggendo ogni
15	 * media come stream dal suo disco e scrivendoli direttamente nella risposta.
16	 *
17	 * Riusabile: oltre al download multiplo dell'AssetManager, sarà la stessa
18	 * funzione di pacchettizzazione usata dalla gallery di condivisione esterna
19	 * (22g).
20	 */
21	class AssetZip
22	{
23	    /**
24	     * Risposta HTTP che invia in streaming uno zip con i media passati.
25	     * I media non leggibili (file mancante sul disco) sono saltati. I nomi
26	     * duplicati sono resi univoci per non sovrascrivere voci nello zip.
27	     *
28	     * @param iterable<int, Media> $media
29	     */
30	    public static function streamResponse(iterable $media, string $downloadName): StreamedResponse
31	    {
32	        return response()->streamDownload(
33	            function () use ($media): void {
34	                // sendHttpHeaders: false → gli header li mette streamDownload;
35	                // qui si scrivono solo i byte dello zip su php://output.
36	                $zip = new ZipStream(sendHttpHeaders: false);
37	
38	                $usedNames = [];
39	                foreach ($media as $item) {
40	                    $stream = self::openStream($item);
41	                    if ($stream === null) {
42	                        continue;
43	                    }
44	
45	                    $name = self::uniqueName((string) $item->file_name, $usedNames);
46	                    $zip->addFileFromStream($name, $stream);
47	                    fclose($stream);
48	                }
49	
50	                $zip->finish();
51	            },
52	            $downloadName,
53	            ['Content-Type' => 'application/zip'],
54	        );
55	    }
56	
57	    /**
58	     * Stream di lettura del file originale del media, o null se assente.
59	     *
60	     * @return resource|null
61	     */
62	    private static function openStream(Media $media)
63	    {
64	        $disk = Storage::disk($media->disk);
65	        $path = $media->getPathRelativeToRoot();
66	
67	        if (! $disk->exists($path)) {
68	            return null;
69	        }
70	
71	        $stream = $disk->readStream($path);
72	
73	        return is_resource($stream) ? $stream : null;
74	    }
75	
76	    /**
77	     * Rende univoco un nome file rispetto a quelli già usati, accodando un
78	     * contatore prima dell'estensione (es. `foto.jpg` → `foto (2).jpg`).
79	     *
80	     * @param array<string, true> $usedNames passato per riferimento, aggiornato
81	     */
82	    private static function uniqueName(string $fileName, array &$usedNames): string
83	    {
84	        $fileName = $fileName !== '' ? $fileName : 'file';
85	
86	        if (! isset($usedNames[$fileName])) {
87	            $usedNames[$fileName] = true;
88	
89	            return $fileName;
90	        }
91	
92	        $extension = pathinfo($fileName, PATHINFO_EXTENSION);
93	        $base = $extension !== '' ? substr($fileName, 0, -(strlen($extension) + 1)) : $fileName;
94	        $suffix = $extension !== '' ? '.' . $extension : '';
95	
96	        $counter = 2;
97	        do {
98	            $candidate = "{$base} ({$counter}){$suffix}";
99	            $counter++;
100	        } while (isset($usedNames[$candidate]));
101	
102	        $usedNames[$candidate] = true;
103	
104	        return $candidate;
105	    }
106	}
